function d_memory_retrieve(P,R){var docs=P.docs||[];var q=P.query_vec||[1,0,0];function cos(a,b){var d=0,na=0,nb=0;for(var i=0;i<a.length;i++){d+=a[i]*b[i];na+=a[i]*a[i];nb+=b[i]*b[i];}return d/(Math.sqrt(na*nb)+1e-9);}var sc=docs.map(function(d){return{id:d.id,sim:+cos(q,d.vec).toFixed(3)};}).sort(function(a,b){return b.sim-a.sim;});return{query:'vector',top:sc.slice(0,3)};}

